@router.get("/notifications/fanout/topics/{topic_key}/buffered-events")
async def get_buffered_topic_events(
    topic_key: str,
    limit: int = 50,
    redis: Redis = Depends(get_redis_client),
    current_user: User = Depends(get_current_user)
):
    if not topic_key.startswith(f"org_{current_user.organization_id}_") and not current_user.is_platform_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized topic key access")
    raw_events = await redis.lrange(f"fanout_history:{topic_key}", 0, min(limit, 100) - 1)
    parsed_events = [json.loads(event) for event in raw_events]
    return {"topic": topic_key, "count": len(parsed_events), "events": parsed_events}
